import {mountAlter} from './alter-face.js';
import {alterDoubleLayout} from './alter-double-model.js';
export const ALTER_DOUBLE_BANKS=Object.freeze([['01 / DELAY',['delay','depth','rate']],['02 / STEREO',['focus','width']],['03 / MIX',['mix']]]);
const x=v=>180+v*145;
const graph='<svg viewBox="0 0 360 132" role="img" aria-label="Panoramique nominal des deux retards"><rect x="1" y="1" width="358" height="130" rx="4" fill="#211711" stroke="#805d47"/>'+[-1,-.5,0,.5,1].map(v=>'<path d="M'+x(v)+' 22V110" stroke="#514035"/>').join('')+'<path data-alter-span stroke="#e3a66e" stroke-width="3"/><circle cx="180" cy="66" r="5" fill="#ebdcc7"/><circle data-alter-l cy="47" r="8" fill="#e3a66e"/><circle data-alter-r cy="85" r="8" fill="#e0c491"/><g font-size="10" fill="#ebdcc7"><text x="35" y="16">L</text><text x="180" y="16" text-anchor="middle">C</text><text x="325" y="16" text-anchor="end">R</text><text x="180" y="123" text-anchor="middle">CONFIGURED PAN · NOT A VECTORSCOPE</text></g></svg>';
export function mountAlterDouble(root,options){return mountAlter(root,{...options,id:'alter-double',title:'DOUBLE 01',subtitle:'DUAL MODULATED DELAY',banks:ALTER_DOUBLE_BANKS,display:graph+'<div class="alter-pro-readouts"><output data-alter-left></output><output data-alter-right></output></div><div class="alter-pro-readouts"><output data-alter-width></output><output data-alter-mix></output><output data-alter-status></output></div><small>Deux retards modulés, coupe-bas commun, panoramiques opposés. Gain direct 1−Mix, gain commun des deux voies Mix/2. Schéma nominal, non mesuré.</small>',footer:'DUAL DELAY · DIFFERENTIAL LFO · HIGH PASS · NATIVE DSP',paint(face,s){const m=alterDoubleLayout(s),[l,r]=m.voices;for(const [id,v] of [['l',l],['r',r]])face.querySelector('[data-alter-'+id+']').setAttribute('cx',x(v.pan));face.querySelector('[data-alter-span]').setAttribute('d','M'+x(l.pan)+' 66H'+x(r.pan));for(const [id,v] of [['left',l],['right',r]])face.querySelector('[data-alter-'+id+']').textContent=(v.delay*1000).toFixed(1)+' ms ± '+Math.abs(v.depth*1000).toFixed(1)+' · '+v.rate.toFixed(2)+' Hz';face.querySelector('[data-alter-width]').textContent='WIDTH '+Math.round(s.width*100)+'%';face.querySelector('[data-alter-mix]').textContent='DRY '+Math.round(m.dry*100)+'% · FX GAIN '+Math.round(m.wet*100)+'%';face.querySelector('[data-alter-status]').textContent=s.enabled===false?'BYPASS':s.mix===0?'DRY':'ACTIVE';}});}
